INSERT INTO essencias (simbolo, nome, cor, cor_fundo, elemento) VALUES ('λ', 'Água', '#4ab0e8', 'rgba(74,176,232,.25)', 'Água');
INSERT INTO essencias (simbolo, nome, cor, cor_fundo, elemento) VALUES ('Φ', 'Ar', '#c8e0f8', 'rgba(200,224,248,.15)', 'Ar');
INSERT INTO essencias (simbolo, nome, cor, cor_fundo, elemento) VALUES ('Ω', 'Fogo', '#e87040', 'rgba(232,112,64,.25)', 'Fogo');
INSERT INTO essencias (simbolo, nome, cor, cor_fundo, elemento) VALUES ('Σ', 'Terra', '#b87840', 'rgba(184,120,64,.25)', 'Terra');
INSERT INTO essencias (simbolo, nome, cor, cor_fundo, elemento) VALUES ('ζ', 'Positiva', '#4ecb7a', 'rgba(78,203,122,.25)', 'Luz');
INSERT INTO essencias (simbolo, nome, cor, cor_fundo, elemento) VALUES ('Ψ', 'Negativa', '#a070e8', 'rgba(160,112,232,.25)', 'Sombra');
INSERT INTO essencias (simbolo, nome, cor, cor_fundo, elemento) VALUES ('ξ', 'Sintética', '#00e5d4', 'rgba(0,229,212,.20)', 'Síntese');
INSERT INTO essencias (simbolo, nome, cor, cor_fundo, elemento) VALUES ('δ', 'Estática', '#ffe84a', 'rgba(255,232,74,.22)', 'Eletricidade');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('pocao-cura', 'Poção de Cura', 'Comum', '❤️', 'ζ ζ', 'Instantânea', '1 maçã vermelha em perfeito estado.', 'Você recupera pontos de vida quando bebe esta poção igual a 1d4 +1. Qualquer que seja a potência, o líquido vermelho da poção cintila quando agitado.', 'A cada ζ adicional à mistura, a cura aumenta em 1d4 + 1.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('elixir-saude', 'Elixir de Saúde', 'Comum', '💚', 'λ ζ', 'Instantânea', '10 gotas de sangue de uma criatura não maligna e saudável.', 'Quando você bebe esta poção, ela cura qualquer doença comum que esteja afligindo você e remove as condições cego, surdo, paralisado e envenenado. O líquido vermelho claro tem pequenas bolhas de luz nele.', 'A cada ζ adicional à mistura ela aumenta a duração em 6 segundos.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('taciturnos-mors', 'Taciturnos Mors', 'Comum', '☠️', 'Ψ Ψ', 'Até ser curado', '1 maçã vermelha em imperfeito estado.', 'Esta mistura parece, cheira e tem o gosto de uma poção de cura, mas é veneno mascarado por ilusão. Ao beber: 1d6 de dano de veneno e teste de Constituição ou fica envenenado sofrendo 1d6 por turno. No fim de cada turno pode repetir o teste.', 'A cada Ψ adicional à mistura, o dano aumenta em 1d6.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('araneolus-paws', 'Araneolus Paws', 'Comum', '🕷️', 'Σ Ψ', '1 hora', '1g de pelo de aranha.', 'Quando bebe esta poção, você ganha grampos nos dedos que concedem deslocamento de escalada igual ao de caminhada por 1 hora. Pode escalar paredes verticais e tetos. Vantagem em Atletismo para escalar. A poção tem camadas marrom, prata e cinza que não se misturam.', 'A cada Ψ adicional à mistura, ela dobra de duração.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('pocao-calor', 'Poção de Calor', 'Comum', '🔥', 'Ω Ω', '1 hora', '50g de pimenta seca triturada.', 'Resistência a dano de frio e imunidade a condições de clima extremamente frio (hipotermia, congelamento). O líquido alaranjado emite vapor e aquece a garganta como brasa ao descer. Deixa o bebedor agradavelmente aquecido mesmo em ventanias geladas.', 'A cada Ω adicional, aumenta a duração da poção em 30 minutos.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('tintura-aquatica', 'Tintura Aquática', 'Comum', '🫧', 'λ λ', '1 hora', 'Um peixe ainda vivo esmagado em 250ml de água corrente.', 'Permite respirar debaixo d''água como se fosse ar. Nadar não custa movimento extra. O líquido azul-esverdeado tem bolhas que sobem infinitamente mesmo com o frasco fechado.', 'A cada λ adicional à mistura, ela dobra de duração.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('tocha-interior', 'Tocha Interior', 'Comum', '🕯️', 'Ω ζ', '1 hora', '1 vaga-lume vivo.', 'O corpo do bebedor emite luz brilhante em 3m e penumbra em 6m. Ataques desarmados causam 1d4 de dano de fogo adicional. O calor emitido não machuca roupas ou pele. Pode ser suprimido e reativado como ação bônus.', 'A cada ζ adicional, aumenta a duração da poção em 30 minutos.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('nevoa-protetora', 'Névoa Protetora', 'Comum', '🌫️', 'λ Φ', '10 minutos', '100ml de orvalho coletado antes do amanhecer.', 'Uma névoa úmida envolve levemente o bebedor. Ataques à distância contra você têm desvantagem (levemente obscurecido). Também amortece o impacto de queda, reduzindo 2d6 de dano. O líquido branco tem consistência de leite e evapora ao abrir.', 'A cada λ adicional, aumenta a duração da poção em 30 minutos.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('tonico-percepcao', 'Tônico da Percepção', 'Comum', '👀', 'Φ ζ', '1 hora', 'Olhos de um predador noturno (morcego, coruja ou gato).', 'Vantagem em testes de Sabedoria (Percepção) e Inteligência (Investigação) baseados em visão ou audição. Ignora a penalidade de Percepção em ambientes com penumbra. O líquido amarelado cintila como ouro líquido.', 'A cada Φ adicional, aumenta a duração da poção em 30 minutos.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('pocao-saltarina', 'Poção Saltarina', 'Comum', '🦘', 'Σ λ', '1 hora', 'Patas traseiras de um sapo vivo, esmagadas em vinagre.', 'Distância de salto triplicada, sem custo de movimento extra para saltar. Aterrissagens nunca causam dano por queda de até 6m. O líquido esverdeado borbulha quando sacudido.', 'A cada Σ adicional, aumenta a duração da poção em 30 minutos.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('unguento-cicatrizante', 'Ungüento Cicatrizante', 'Comum', '🩹', 'ζ Σ', 'Instantânea', '15g de teia de aranha seca e 5ml de mel.', 'Estabiliza uma criatura moribunda instantaneamente e cura 1d6 PV. Aplicar é uma ação e funciona pelo toque. O ungüento grosso e dourado tem cheiro adocicado e endurece na ferida como uma crosta protetora.', NULL);
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('pocao-voz', 'Poção de Voz', 'Comum', '🎵', 'Φ Σ', '1 hora', 'Língua de pássaro cantor seca ao sol.', 'Voz carrega 3× mais longe do que o normal. +1 em testes de Carisma (Persuasão) e Carisma (Atuação). A voz adquire qualidade rica e ressonante. O líquido âmbar tem sabor de mel e ervas aromáticas.', 'A cada Φ adicional, aumenta a duração da poção em 30 minutos.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('tonico-calmante', 'Tônico Calmante', 'Comum', '😌', 'λ Σ', '1 hora', '200ml de leite de vaca ordenhado ao anoitecer.', 'Remove a condição Amedrontado imediatamente ao beber. Enquanto durar, vantagem em testes de resistência contra ser Amedrontado ou Encantado. O líquido branco leitoso tem cheiro de ervas e camomila.', 'A cada Σ adicional, aumenta a duração da poção em 30 minutos.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('veneno-contato', 'Veneno de Contato', 'Comum', '🐍', 'Ψ Ω', '1 hora', 'Glândula de veneno de serpente fresca.', 'Ataques corpo a corpo causam 1d4 de dano de veneno adicional. O alvo deve ter sucesso num teste de Constituição (CD 12) ou fica Envenenado até o início do próximo turno. O líquido verde-escuro tem bolhas viscosas na superfície.', 'A cada Ψ adicional, aumenta a duração da poção em 30 minutos.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('pocao-estimulante', 'Poção Estimulante', 'Comum', '⚡', 'ζ λ', '1 hora', 'Grãos de café moídos fervidos em água de nascente.', 'Remove 1 nível de Exaustão imediatamente ao beber. Enquanto durar, vantagem em testes de Iniciativa. Você não precisa dormir pelo período de duração sem sofrer exaustão por isso. O líquido marrom-escuro tem cheiro forte de café.', 'A cada ζ adicional, aumenta a duração da poção em 30 minutos.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('oleo-iluminacao', 'Óleo de Iluminação', 'Comum', '💡', 'Ω Σ', '8 horas', '50g de fósforo em pó.', 'Cobre um objeto do tamanho de uma mão com óleo luminescente. O objeto coberto emite luz brilhante em 3m e penumbra em 6m sem produzir calor. Pode ser apagado e reaceso como ação bônus. Pode cobrir até 3 objetos por frasco.', 'A cada Ω adicional, o raio de luz dobra.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('elixir-foco', 'Elixir de Foco', 'Comum', '🎯', 'ζ Φ', '1 hora', 'Ovo de coruja chocado mas não eclodido.', 'Vantagem em testes de Constituição para manter Concentração em magias ao sofrer dano. Ataques à distância ignoram penalidade por alvo em cobertura leve. O líquido cristalino tem um pequeno foco luminoso flutuando em seu interior.', 'A cada Φ adicional, aumenta a duração da poção em 30 minutos.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('nevoa-fetida', 'Névoa Fetida', 'Comum', '🤢', 'λ Ψ', '10 minutos', 'Tinta de lula misturada com 50ml de água de pântano.', 'O alvo começa a soltar uma névoa negra em 1,5m ao redor exalando um odor desagradável e fazendo com que alvos dentro da névoa tenham desvantagem em testes de percepção. O frasco parece conter fumaça sólida que não escapa ao abrir.', 'A cada Ψ adicional, o raio da névoa aumenta em 1,5m.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('pocao-sussurros', 'Poção de Sussurros', 'Comum', '💬', 'Φ Ψ', '10 minutos', 'Orelha de um animal com audição aguçada (lobo, coelho ou cervo).', 'Comunica-se telepaticamente com criaturas consentidas a até 30m que conheçam pelo menos um idioma que você fale. A comunicação é silenciosa. O líquido prateado tem ondas circulares que se propagam sem parar.', 'A cada Φ adicional, o alcance dobra.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('vitalidade-sombria', 'Vitalidade Sombria', 'Comum', '🩸', 'ζ Ψ', '1 minuto', 'Coração de um predador (lobo, leão ou urso) retirado em 1 minuto após a morte.', 'Ganha presas afiadas. Ao reduzir uma criatura a 0 PV em corpo a corpo, pode usar uma reação para morder o alvo recuperar PV iguais ao modificador de Constituição (mínimo 1). O líquido vermelho-escuro pulsa ritmicamente e parece mais quente que o ambiente.', 'A cada Ψ adicional, a recuperação aumenta em uma quantidade igual ao modificador.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('pele-reptil', 'Pele de Réptil', 'Comum', '🦎', 'ζ Ω', '1 minuto', 'Escama de réptil grande (crocodilo, lagarto-monitor ou iguana).', 'Enquanto não usar armadura nem escudo, sua CA = 13 + modificador de Destreza. Escamas semi-transparentes cobrem a pele do bebedor. Resistência a temperaturas extremas (calor e frio). O líquido esverdeado tem textura escamosa visível.', NULL);
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('vitalidade-muscular', 'Vitalidade Muscular', 'Comum', '💪', 'Σ ζ', '1 minuto', '200g de carne bovina crua batida com sal.', '+2 em testes de Força e testes de resistência de Força. Ataques com armas que usam Força causam 1 ponto extra de dano. O líquido marrom-avermelhado tem cheiro forte e ferroso.', 'A cada Σ adicional, dobra a duração da poção.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('isolante-eletrico', 'Isolante Elétrico', 'Comum', '🌩️', 'δ λ', '1 minuto', '50g de âmbar triturado e 100ml de água destilada.', 'Resistência a dano elétrico. Imune à paralisia causada por choques elétricos ou raios. Útil em tempestades, masmorras com enguias-trovão ou armadilhas elétricas. O líquido âmbar crackle com faíscas estáticas que percorrem o frasco.', 'A cada δ adicional, dobra a duração da poção.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('primer-sintetico', 'Primer Sintético', 'Comum', '🧴', 'ξ λ', '1 hora', '100ml de resina de árvore purificada e destilada.', 'Líquidos naturais (chuva, lama, sangue, ácidos naturais) deslizam do bebedor sem afetar. Vantagem em testes de resistência contra efeitos baseados em substâncias líquidas. Superfície parece levemente hidrofóbica. O líquido incolor parece escorrer do frasco mesmo quando fechado.', 'A cada ξ adicional, aumenta a duração da poção em 30 minutos.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('tonico-sintetico', 'Tônico Sintético', 'Comum', '🧪', 'ξ ζ', 'instantânea', '5 folhas de carvão ativo triturado em vinagre.', 'Neutraliza venenos mundanos no organismo instantaneamente. Imune ao estado Envenenado causado por substâncias não mágicas. Álcool não produz efeito. Ideal contra venenos de criaturas comuns, comida estragada ou bebidas adulteradas. O líquido preto-carvão não tem sabor.', NULL);
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('estimulante-eletrico', 'Estimulante Elétrico', 'Comum', '⚡', 'δ ζ', '1 minuto', 'Célula galvânica primitiva (zinco e cobre em salmoura).', 'Vantagem em testes de resistência contra ser Paralisado ou Atordoado. +3m de velocidade de caminhada. O líquido azul-elétrico faísca ao ser sacudido.', 'A cada δ adicional, dobra a duração da poção.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('amortentia', 'Amortentia', 'Incomum', '🩷', 'λ Ω ζ Ψ', '12 horas', 'Coração de um mamífero.', 'Da próxima vez que você vir uma criatura dentro de 10 minutos após beber esse filtro, você fica enfeitiçado por essa criatura por 12 horas. Se a criatura for da espécie ou gênero que você normalmente é atraído, você a reconhece como seu amor verdadeiro. O líquido efervescente de coloração rosa contém uma bolha em formato de coração difícil de perceber.', 'A cada ζ Ψ adicional à mistura, ela dobra de duração.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('endurecimento', 'Endurecimento', 'Incomum', '🪨', 'Σ Ω Σ Ω', '1 minuto', '200g de argila vulcânica.', 'Pele endurece como basalto: +1 CA (não cumulativo com armadura pesada). O bebedor parece levemente mais pesado e seus movimentos produzem um leve som pedregoso.', 'A cada Σ Ω adicional, o bônus de CA aumenta em +1.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('oleo-precisao', 'Óleo de Precisão', 'Incomum', '⚔️', 'Ω Φ Ω Ω', '1 hora', '100g de minério de prata em pó.', 'Este óleo claro e gelatinoso cintila com minúsculos fragmentos de prata ultrafinos. O óleo pode cobrir uma arma cortante ou perfurante ou até 5 munições. Por 1 hora, o item coberto será mágico e terá +1 de bônus nas jogadas de ataque e dano.', 'A cada Ω Ω adicional à mistura, o bônus aumenta em +1.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('oleo-escorregadio', 'Óleo Escorregadio', 'Incomum', '💧', 'λ Σ λ Σ', '8 horas', '1kg de Argila seca.', 'Unguento negro pegajoso que ao cobrir uma criatura Média ou menor concede os efeitos da magia movimentação livre por 8 horas. Alternativamente, pode ser derramado no chão cobrindo 3m quadrados com efeito de área escorregadia por 8 horas. Criaturas devem testar Destreza ou caem.', 'A cada λ Σ adicional à mistura, ela dobra de duração.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('loqui-animalibus', 'Loqui Animalibus', 'Incomum', '🐾', 'Σ ζ Σ Φ', '24 horas', 'Um pedaço de um animal que ainda esteja vivo.', 'Quando beber esta poção, você pode conjurar a mágica amizade animal por 24 horas, à vontade. Agitar este líquido turvo traz pedacinhos à vista: uma escama de peixe, uma língua de colibri, uma garra de gato ou pelo de um esquilo.', 'A cada Σ Φ adicional à mistura, ela dobra de duração.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('constructio', 'Constructio', 'Incomum', '💪', 'Ω Σ Σ ζ', '1d4 horas', '15 mg de Proteína.', 'Quando beber esta poção, você ganha o efeito de "aumentar" da magia aumentar/reduzir por 1d4 horas (sem concentração). O vermelho no líquido da poção expande constantemente em uma gota minúscula e então contrai.', 'A cada Σ Φ adicional, ela dobra de duração. A cada Ω Σ Σ ζ adicional, o efeito de aumentar dobra.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('reformido', 'Reformido', 'Incomum', '🔻', 'λ Φ Φ Ψ', '1d4 horas', '150g de Farinha.', 'Quando beber esta poção, você ganha o efeito de "reduzir" da magia aumentar/reduzir por 1d4 horas (sem concentração). O vermelho no líquido contrai constantemente em uma gota minúscula e expande para colorir o líquido ao redor.', 'A cada Φ Ψ adicional, ela dobra de duração. A cada Ω Σ Σ ζ adicional, o efeito de diminuir dobra.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('piscis-nasus', 'Piscis Nasus', 'Incomum', '🐟', 'λ λ λ Φ', '24 horas', 'Um peixe que morreu asfixiado.', 'Você desenvolve guelras e pode respirar embaixo d''água por 24 horas após beber esta poção. Seu fluido verde nebuloso cheira a maresia e possui uma bolha similar a uma água-viva flutuando nele.', 'A cada λ Φ adicional à mistura, ela dobra de duração.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('draconicum-spiritus', 'Draconicum Spiritus', 'Incomum', '🐉', 'Ω Ω Ω Ω', '1 hora (ou 5 usos)', 'Uma escama de réptil.', 'Quando bebe esta poção, você pode usar ação bônus para exalar fogo em alvo a 9m (Destreza ou metade do dano). 4d6 de dano de fogo. O efeito termina após 5 expirações ou 1 hora. O líquido laranja lampeja e fumaça vaza quando aberto.', 'A cada Ω Ω adicional, o dano aumenta em 1d6.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('leao-engarrafada', 'Leão Engarrafada', 'Incomum', '🦁', 'Σ Σ Ψ Ψ', '24 horas', '1L de sangue de leão.', '+1d4 em testes de Força e testes de resistência, +2 ao dano com armas de Força e imunidade ao medo por 24 horas. Comportamentos de risco e agressão excessiva. Vício: CD crescente de Constituição; falha causa dependência com penalidade de –2 em Força e Constituição na abstinência.', 'A cada Ψ Ψ adicional, ela dobra de duração. A cada Σ Σ Ψ Ψ, bônus de dano aumenta em +1.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('protecao-elemental', 'Proteção Elemental', 'Incomum', '🛡️', 'λ Ω Σ Φ', '1 hora', '5 folhas de papel de grimório.', 'Poção viscosa multicolorida com cheiro de Camomila. Resistência a um tipo de dano (fogo, frio, elétrico, trovejante ou ácido) por 1 hora. O tipo é definido na fabricação da poção.', 'A cada λ Ω Σ Φ adicional, concede uma resistência elemental adicional.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('granadas-explosivas', 'Granadas Explosivas', 'Incomum', '💣', 'λ Φ Ω Ω', 'Instantânea', '25g de Pólvora.', 'Frasco aerodinâmico com líquido instável e quente. Pode ser arremessado em ponto a 18m. Criaturas a 4,5m devem testar Destreza (CD 14) ou sofrem 2d6 de dano (tipo escolhido na fabricação: fogo, frio, elétrico, trovejante ou ácido).', 'A cada Ω Ω adicional, o dano aumenta em 1d6.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('elixir-coragem', 'Elixir de Coragem', 'Incomum', '🦁', 'Ψ Ω ζ', '1 hora', 'Coração de um gladiador que morreu em combate justo.', 'Imunidade às condições Amedrontado e Encantado. +1d4 em todas as jogadas de ataque. Ao ser reduzido a 0 PV, pode continuar lutando com 1 PV pelo próximo turno (uma vez por duração). O líquido vermelho-ouro ferve levemente ao contato com o ar.', 'A cada ζ adicional, o bônus de ataque aumenta em +1d4.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('fluido-memoria', 'Fluido de Memória', 'Incomum', '🧠', 'ξ Φ ζ', '8 horas', 'Lâmina frontal de um crânio humano polida até espelhar.', 'Lembra-se perfeitamente de absolutamente tudo que ver, ouvir ou ler. Vantagem em testes de Inteligência (História), (Arcana) e (Religião). Pode reproduzir textos ou mapas vistos com fidelidade total. O líquido incolor tem textura cristalina.', 'A cada ξ adicional, estende a memória perfeita retroativamente em 24 horas.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('descarga-estatica', 'Descarga Estática', 'Incomum', '⚡', 'δ δ ζ', '1 hora', '50g de enxofre em pó e uma moeda de cobre.', 'Ao ser atingido por ataque corpo a corpo, o atacante sofre 1d6 de dano elétrico. Ao tocar uma superfície metálica deliberadamente, pode descarregar 2d6 elétrico em ponto adjacente (ação bônus). O corpo emite faíscas visíveis no escuro.', 'A cada δ adicional, o dano de reação aumenta em 1d6.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('elixir-condutor', 'Elixir Condutor', 'Incomum', '🗡️', 'δ Σ Ω', '1 hora', 'Fio de cobre puro fundido em resina.', 'Uma arma corpo a corpo tocada passa a causar 1d8 extra de dano elétrico. Ao acertar, o alvo não pode realizar reações até o início do próximo turno dele (descarga paralisante momentânea). Uma arma por vez; trocar é ação bônus.', 'A cada δ adicional, o dano elétrico aumenta em 1d8.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('catalisador-essencia', 'Catalisador de Essência', 'Incomum', '⚗️', 'ξ ξ ζ', 'Até usar (máx. 1 hora)', 'Farinha de pedra filosofal bruta (inerte, 50g).', 'A próxima poção que beber tem duração e efeito dobrados (curas, danos e bônus numéricos). Não afeta poções instantâneas de cura (mas dobra a cura). Não pode ser bebido em conjunto com outra poção. O líquido prateado tem a consistência de mercúrio.', 'A cada ξ adicional, afeta as próximas 2 poções.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('forma-sancto', 'Forma Sancto', 'Rara', '🌫️', 'Σ Φ Φ ζ ζ Ψ', '8 horas', '100ml de Água parada a mais de 24h.', 'Óleo cinzento nebuloso que pode cobrir uma criatura Média ou menor (frasco extra por categoria acima de Médio). Aplicar leva 10 minutos. A criatura afetada recebe o efeito da magia forma etérea por 8 horas.', 'A cada ζ ζ Ψ adicional, ela dobra de duração.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('oculi-tertii', 'Oculi Tertii', 'Rara', '👁️', 'Ω Φ Φ ζ Φ Ψ', '1 hora', '15 mg de Proteína.', 'Quando beber esta poção, você ganha os benefícios da magia clarividência por 1 hora (sem concentração). Um globo ocular sacoleja dentro desse líquido amarelado, mas desaparece quando a poção é aberta.', 'A cada ζ Φ Ψ adicional, ela dobra de duração.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('gas-corpus', 'Gas Corpus', 'Rara', '🌁', 'Σ Φ Φ Ψ λ Φ', '8 horas', '1l de água fervida.', 'Quando beber esta poção, você ganha os efeitos da magia forma gasosa por 8 horas (sem concentração) ou até terminar com ação bônus. O recipiente parece conter névoa que se move e flui como água.', 'A cada Ψ λ Φ adicional, ela dobra de duração.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('gigas-fortitudo', 'Gigas Fortitudo', 'Rara', '🏋️', 'Σ Ψ Ω Ψ Σ ζ', '1 hora', '500g de Carne fresca.', 'Quando beber esta poção, seu valor de Força muda para 23 por 1 hora (sem efeito se Força ≥ 23). O líquido transparente tem bolas de carne flutuando no topo.', 'A cada Ψ Σ ζ adicional, o valor de Força alterado aumenta em 2.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('heroism', 'Heroism', 'Rara', '🛡️', 'Ω ζ ζ ζ Σ ζ', '1 hora', '10ml de água benta.', 'Por 1 hora, você ganha 10 pontos de vida temporários e está sob efeito da magia benção (sem concentração). Esta poção azul borbulha e fumega como se estivesse fervendo.', 'A cada ζ Σ ζ adicional, ela dobra de duração. A cada ζ ζ Σ ζ adicional, os PV temporários aumentam em 10.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('lectorem-mentis', 'Lectorem Mentis', 'Rara', '🧠', 'Φ Ψ Σ Ψ λ Ψ', '1 hora', 'Uma orelha cozida em 1L de água com 150g de açúcar.', 'Quando beber esta poção, você ganha os efeitos da magia detectar pensamentos por 1 hora (sem concentração). O líquido roxo denso tem uma nuvem ovóide rosa flutuando nele.', 'A cada Ψ λ Ψ adicional, ela dobra de duração.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('pocao-voo', 'Poção de Voo', 'Rara', '🦅', 'Φ Φ Φ Φ Φ Φ', '24 horas', 'Um falcão adulto inteiro fêmea.', 'Você ganha deslocamento de voo igual ao de caminhada por 24 horas e pode planar. Se estiver no ar quando o efeito acabar e sem outro meio de sustentação, cai. O líquido transparente flutua no topo do recipiente.', 'A cada Φ Φ Φ adicional, ela dobra de duração.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('newkama-hormone', 'Newkama Hormone', 'Rara', '🌸', 'Ω Ω λ λ λ Ω λ Ω', '24 horas', '10mL de fluido hormonal de humanóide coletado em período específico.', 'Líquido transparente com brilho prateado. Ao bebê-la, o usuário vivencia uma transformação temporária, mudando seu sexo biológico por 24 horas com todos os atributos correspondentes.', 'A cada λ Ω λ Ω adicional, ela dobra de duração.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('liliths-arcanus', 'Liliths Arcanus', 'Rara', '🔵', 'Ω Ω λ Ω Ω ζ', 'Instantânea', '5 folhas de papel de grimório.', 'Vários tons de azuis vibrantes e líquido viscoso. Role 1d4+1 — recupera espaços de magia com nível combinado igual ou menor que o resultado (5° nível ou menor). Sem efeito se não tiver espaços de magia.', 'A cada λ Ω ζ adicional, a restauração aumenta em +1.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('transmutacao-sintetica', 'Transmutação Sintética', 'Rara', '🦊', 'ξ ξ Σ Σ', '1 hora', 'Pele inteira de um animal selvagem (coelho, raposa ou lobo).', 'Transforma o bebedor em uma besta pequena ou média (NC ≤ 1) à escolha, sem concentração. Mantém memória e personalidade, mas assume atributos físicos da besta. Pode terminar como ação bônus. O líquido muda de cor conforme a besta pensada.', 'A cada ξ adicional, o NC máximo da besta permitida aumenta em 1.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('tempestade-estatica', 'Tempestade Estática', 'Rara', '🌩️', 'δ δ Ω Ω', '10 minutos (2 usos)', 'Vidro fundido por um raio (fulgurita), 30g.', 'Armazena uma tempestade elétrica concentrada. Até 2 vezes como ação bônus: lança um raio (60m, 3d6 elétrico, CD 14 Destreza ou metade). Ao usar o segundo raio, o frasco explode causando 2d6 elétrico no próprio usuário.', 'A cada δ adicional, o dano do raio aumenta em 1d6.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('invisibilitas', 'Invisibilitas', 'Muito Rara', '👻', 'Φ Φ Φ Φ ζ ζ Φ ζ', '1 hora', '3,14g de vidro em pó.', 'O recipiente aparenta estar vazio, mas parece conter um líquido. Quando bebe, você fica invisível por 1 hora como invisibilidade maior (sem concentração). Atacar ou conjurar magia encerra o efeito.', 'A cada ζ ζ Φ ζ adicional, ela dobra de duração.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('invulnerabilis', 'Invulnerabilis', 'Muito Rara', '🔮', 'Σ Σ Σ Σ λ Ω Σ Φ', '1 minuto', '3g de unhas, 6 fios de cabelo e 9 dentes de réptil.', 'Por 1 minuto após beber esta poção, você adquire resistência a todos os danos. O líquido xaroposo parece ferro derretido.', 'A cada λ Ω Σ Φ adicional, ela aumenta a duração em 1 hora.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('longivitas', 'Longivitas', 'Muito Rara', '⌛', 'ζ Ψ ζ Ψ ζ ζ Ψ Ψ', 'Permanente', '1L de Sangue de humanóide fêmea virgem retirado enquanto adormecida e sem ferimentos.', 'Sua idade física é reduzida em 1d6+6 anos (mínimo puberdade). Cada vez subsequente há 10% de chance cumulativa de envelhecer 1d6+6 anos em vez de rejuvenescer. Suspensas no líquido âmbar há criaturas mortas que desaparecem ao abrir.', 'A cada ζ ζ Ψ Ψ adicional, a quantidade de anos dobra.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('accelerare', 'Accelerare', 'Muito Rara', '⚡', 'Φ Φ Φ Φ Ψ Ψ Φ Ψ', '10 minutos', '3 asas de ave de rapina, 3 pés de lebre, 3 cabeças de beija-flor.', 'Você ganha os efeitos da magia velocidade por 10 minutos (sem concentração). O fluido amarelo da poção é matizado de preto e gira em torno de si.', 'A cada Ψ Ψ Φ Ψ adicional, ela dobra de duração.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('vitalis', 'Vitalis', 'Muito Rara', '🌟', 'Σ Σ λ λ Ψ Ψ Σ Ψ', '24 horas', '1L de sangue de humanóide macho exausto no momento da coleta.', 'Remove toda exaustão e cura doenças ou venenos não mágicos. Pelas próximas 24 horas, você recupera o valor máximo de PV para cada Dado de Vida gasto. O líquido carmesim pulsa regularmente.', 'A cada Ψ Ψ Σ Ψ adicional, ela dobra de duração.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('ambrosia', 'Ambrosia', 'Muito Rara', '💀', 'Ψ Ψ Ψ Ψ Ψ Ψ Ψ Ψ', 'Instantânea', '10g de restos mortais da mãe da criatura, 10L de sangue de humanóide que morreu em terror, dois meios-corações de bode.', 'Derramada sobre restos mortais, traz de volta um morto (alma disposta e livre) com 1 PV. Cura venenos e doenças normais da hora da morte. O alvo sofre –7 de penalidade em tudo, reduzida em 1 a cada descanso longo.', 'Com Ψ Ψ Ψ Ψ adicional, a criatura volta com vida máxima e sem penalidade.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('felix-felicis', 'Felix Felicis', 'Muito Rara', '🍀', 'ζ ζ ζ ζ ζ ζ ζ ζ', '1 hora', '100g de obsidiana em pó peneirada.', 'Sorte Líquida por 1 hora: +2 em todos os d20, +10 em d100. Rolagens < 10 no d20 contam como 10; < 50 no d100 contam como 50.', 'A cada ζ ζ ζ ζ adicional, ela dobra de duração.');
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('liliths-praestans', 'Liliths Praestans Praesidium', 'Lendária', '✨', 'Σ Σ ζ ζ ζ ζ λ ζ λ ζ ζ ζ', 'Instantânea', '10g de Éter.', 'Quando beber esta poção, você recupera todos os seus pontos de vida e aumenta sua vida máxima em 30. Além disso, é curado de cegueira, surdez e qualquer doença que esteja o afetando. O líquido tem a cor vívida de sangue e brilha quando agitado.', NULL);
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('garrafa-descanso', 'Garrafa de Descanso Longo', 'Lendária', '💤', 'Σ Σ Ω Ω Ω Σ ζ ζ ζ ζ Ω Ω', '24 horas (efeito)', '100g de diamante em pó, 50g de esmeralda e 25g de ouro.', 'Criado pelo mago Mordekainer. A criatura ganha todos os benefícios de descanso longo, mas após 24h dorme por semanas iguais à quantidade de garrafas consumidas (embora possa gastar DV para curar durante o sono). Parece alcatrão que brilha como diamantes.', NULL);
INSERT INTO pocoes (id, nome, raridade, icone, formula, duracao, nucleo, descricao, melhoria) VALUES ('trembolona', 'Trembolona', 'Lendária', '💉', 'Σ Σ ξ Σ Σ ξ Σ Σ ξ Σ Σ ξ', 'Permanente (cumulativo, máx. Força 28)', '100L de fluido de baleia coletado nas últimas 24h enquanto o animal estava saudável.', 'Líquido carmesim com bolhas pretas sem parar. Aumenta seu valor de Força em 3, até máximo de 28. Pode ser tomado múltiplas vezes (cumulativo). Cada dose adicional tem 10% de chance cumulativa de causar insuficiência cardíaca (mortal).', NULL);